/// All species names in enum order: the canonical dex order (1..=151) plus any
/// extra `pokemon/*.json` files discovered on disk (IDs 152+), sorted by
/// filename. Species added through the editor are picked up automatically —
/// existing dex numbers stay stable, extras are appended.
fn species_names_in_order(manifest_dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = SPECIES_ORDER.iter().map(|s| (*s).to_string()).collect();
    append_extra_json_names(&mut names, &manifest_dir.join("pokemon"), SPECIES_ORDER);
    names
}

/// All move names in `MoveId` order (Pound=0x01..Struggle=0xA5) plus any extra
/// `moves/*.json` files discovered on disk (IDs 0xA6+), sorted by filename.
fn move_names_in_order(manifest_dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = MOVE_ORDER.iter().map(|s| (*s).to_string()).collect();
    append_extra_json_names(&mut names, &manifest_dir.join("moves"), MOVE_ORDER);
    names
}

/// Append `.json` file stems in `dir` not already in `base`, sorted by
/// filename — the extension channel for records added through the editor.
fn append_extra_json_names(names: &mut Vec<String>, dir: &Path, base: &[&str]) {
    println!("cargo:rerun-if-changed={}", dir.display());
    let mut extras: Vec<String> = fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("read_dir {}: {}", dir.display(), e))
        .filter_map(|r| r.ok())
        .filter(|e| e.path().extension().map_or(false, |x| x == "json"))
        .map(|e| e.path().file_stem().unwrap().to_string_lossy().into_owned())
        .filter(|n| !base.contains(&n.as_str()))
        .collect();
    extras.sort();
    names.extend(extras);
}

/// Item names in `ItemId` order: the `data/items/item_list.json` order
/// (NoItem=0x00, first list entry=0x01, …) plus the fixed Hm01-05/Tm01-50
/// variants (0xC4..=0xFA, hardcoded — they are not in item_list.json).
fn item_names_in_order(manifest_dir: &Path) -> Vec<String> {
    let items_dir = manifest_dir.join("data/items");
    let list_path = items_dir.join("item_list.json");
    let list_text = fs::read_to_string(&list_path)
        .unwrap_or_else(|e| panic!("read {}: {}", list_path.display(), e));
    let list_json: serde_json::Value = serde_json::from_str(&list_text)
        .unwrap_or_else(|e| panic!("parse {}: {}", list_path.display(), e));
    let mut names: Vec<String> = list_json["items"]
        .as_array()
        .unwrap_or_else(|| panic!("{}: missing 'items' array", list_path.display()))
        .iter()
        .map(|v| {
            v.as_str()
                .unwrap_or_else(|| panic!("{}: item name not a string", list_path.display()))
                .to_string()
        })
        .collect();
    // TM/HM ids live in the fixed 0xC4..=0xFA range (original GB table).
    for i in 1..=5 {
        names.push(format!("Hm{:02}", i));
    }
    for i in 1..=50 {
        names.push(format!("Tm{:02}", i));
    }
    names
}

/// Emits `items_gen.rs` — the `ItemId` enum (full derive set + explicit
/// `#[repr(u8)]` discriminants), generated from `data/items/item_list.json`
/// so items added through the editor become real enum variants on the next
/// build. `NoItem = 0x00`; the canonical list order keeps its byte IDs
/// (0x01..=0x53, extras appended after the base list); Hm01-05 = 0xC4..0xC8
/// and Tm01-50 = 0xC9..0xFA keep the fixed original-GB ids.
fn generate_item_enum(manifest_dir: &Path, out_dir: &str) {
    let names = item_names_in_order(manifest_dir);
    let out_path = Path::new(out_dir).join("items_gen.rs");
    let mut out = fs::File::create(&out_path).expect("create items_gen.rs");
    write_enum_header(&mut out, "ItemId");
    writeln!(out, "    NoItem = 0x00,").unwrap();
    for (i, name) in names.iter().enumerate() {
        // Regular list entries keep their position (0x01..=0x53, extras
        // appended after); Hm01-05 / Tm01-50 carry fixed original-GB ids.
        let id = if let Some(n) = name.strip_prefix("Hm") {
            0xC4 + n.parse::<usize>().unwrap() - 1
        } else if let Some(n) = name.strip_prefix("Tm") {
            0xC9 + n.parse::<usize>().unwrap() - 1
        } else {
            i + 1
        };
        writeln!(out, "    {} = 0x{:02X},", name, id).unwrap();
    }
    writeln!(out, "}}").unwrap();
}

/// Emits `species_gen.rs` — the `Species` enum (full derive set + explicit
/// `#[repr(u8)]` discriminants), generated from the `pokemon/*.json` filenames
/// so species added through the editor become real enum variants on the next
/// build. `None = 0`, the canonical dex order keeps its IDs (1..=151), extras
/// get 152+ in filename order.
fn generate_species_enum(manifest_dir: &Path, out_dir: &str) {
    let names = species_names_in_order(manifest_dir);
    let out_path = Path::new(out_dir).join("species_gen.rs");
    let mut out = fs::File::create(&out_path).expect("create species_gen.rs");
    write_enum_header(&mut out, "Species");
    writeln!(out, "    None = 0,").unwrap();
    for (i, name) in names.iter().enumerate() {
        writeln!(out, "    {} = {},", name, i + 1).unwrap();
    }
    writeln!(out, "}}").unwrap();
}

/// Emits `moves_gen.rs` — the `MoveId` enum (full derive set + explicit hex
/// discriminants), generated from the `moves/*.json` filenames. `None = 0x00`,
/// the canonical order keeps its byte IDs (0x01..=0xA5), extras get 0xA6+ in
/// filename order.
fn generate_moves_enum(manifest_dir: &Path, out_dir: &str) {
    let names = move_names_in_order(manifest_dir);
    let out_path = Path::new(out_dir).join("moves_gen.rs");
    let mut out = fs::File::create(&out_path).expect("create moves_gen.rs");
    write_enum_header(&mut out, "MoveId");
    writeln!(out, "    None = 0x00,").unwrap();
    for (i, name) in names.iter().enumerate() {
        writeln!(out, "    {} = 0x{:02X},", name, i + 1).unwrap();
    }
    writeln!(out, "}}").unwrap();
}

/// Writes the derive block + `#[repr(u8)]` + `pub enum <name> {` opening.
/// Derives are emitted fully-qualified so the generated file needs no imports
/// (it is `include!`d into `species.rs` / `moves.rs`).
fn write_enum_header<W: Write>(out: &mut W, name: &str) {
    writeln!(out, "// @generated by pokered-data/build.rs — do not edit.").unwrap();
    writeln!(out, "#[derive(").unwrap();
    writeln!(out, "    Debug,").unwrap();
    writeln!(out, "    Clone,").unwrap();
    writeln!(out, "    Copy,").unwrap();
    writeln!(out, "    PartialEq,").unwrap();
    writeln!(out, "    Eq,").unwrap();
    writeln!(out, "    Hash,").unwrap();
    writeln!(out, "    PartialOrd,").unwrap();
    writeln!(out, "    Ord,").unwrap();
    writeln!(out, "    serde::Serialize,").unwrap();
    writeln!(out, "    serde::Deserialize,").unwrap();
    writeln!(out, "    strum_macros::Display,").unwrap();
    writeln!(out, "    strum_macros::EnumCount,").unwrap();
    writeln!(out, "    strum_macros::EnumIter,").unwrap();
    writeln!(out, "    strum_macros::EnumString,").unwrap();
    writeln!(out, "    num_derive::FromPrimitive,").unwrap();
    writeln!(out, "    num_derive::ToPrimitive,").unwrap();
    writeln!(out, ")]").unwrap();
    writeln!(out, "#[repr(u8)]").unwrap();
    writeln!(out, "pub enum {} {{", name).unwrap();
}

fn write_header<W: Write>(out: &mut W) {
    writeln!(out, "// @generated by pokered-data/build.rs — do not edit.").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "/// A custom tileset registered via `tileset_extras.json`.").unwrap();
    writeln!(out, "pub struct CustomTileset {{").unwrap();
    writeln!(out, "    /// PascalCase identifier used in `MapHeaderJson.tileset`.").unwrap();
    writeln!(out, "    pub name: &'static str,").unwrap();
    writeln!(
        out,
        "    /// PascalCase identifier of the built-in tileset to inherit metadata from."
    )
    .unwrap();
    writeln!(out, "    pub base: &'static str,").unwrap();
    writeln!(
        out,
        "    /// File stem of the cloned PNG under `gfx/tilesets/` (e.g. `\"my_tileset\"`)."
    )
    .unwrap();
    writeln!(out, "    pub png_basename: &'static str,").unwrap();
    writeln!(out, "    /// Embedded `.bst` bytes for this tileset.").unwrap();
    writeln!(out, "    pub blockset: &'static [u8],").unwrap();
    writeln!(
        out,
        "    /// Optional per-tileset passable-tile override list."
    )
    .unwrap();
    writeln!(out, "    pub passable_override: Option<&'static [u8]>,").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn write_empty<W: Write>(out: &mut W) {
    writeln!(out, "pub static CUSTOM_TILESETS: &[CustomTileset] = &[];").unwrap();
}

#[derive(Debug)]
struct ExtraEntry {
    base: String,
    bst_file: String,
    png_file: String,
}

/// Hand-rolled minimal JSON reader so the build script doesn't need `serde`.
/// The file shape we expect is:
/// ```json
/// { "MyTileset": { "base": "Overworld", "bstFile": "my_tileset.bst",
///                  "pngFile": "my_tileset.png", ... }, ... }
/// ```
fn read_extras(path: &Path) -> Vec<(String, ExtraEntry)> {
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return Vec::new(),
    };
    let value: JsonValue = match parse_json(&text) {
        Some(v) => v,
        None => {
            println!(
                "cargo:warning=tileset_extras.json could not be parsed; ignoring custom tilesets"
            );
            return Vec::new();
        }
    };
    let map = match value {
        JsonValue::Object(m) => m,
        _ => return Vec::new(),
    };
    let mut out = Vec::new();
    for (name, entry) in map {
        let entry_map = match entry {
            JsonValue::Object(m) => m,
            _ => continue,
        };
        let lookup = |k: &str| entry_map.iter().find(|(ek, _)| ek == k).map(|(_, v)| v);
        let base = match lookup("base") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => continue,
        };
        let bst_file = match lookup("bstFile") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => continue,
        };
        let png_file = match lookup("pngFile") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => continue,
        };
        out.push((
            name,
            ExtraEntry {
                base,
                bst_file,
                png_file,
            },
        ));
    }
    // Stable order for reproducible builds.
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

fn read_overrides(path: &Path) -> BTreeMap<String, Vec<u8>> {
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return BTreeMap::new(),
    };
    let value: JsonValue = match parse_json(&text) {
        Some(v) => v,
        None => return BTreeMap::new(),
    };
    let map = match value {
        JsonValue::Object(m) => m,
        _ => return BTreeMap::new(),
    };
    let mut out = BTreeMap::new();
    for (name, entry) in map {
        if let JsonValue::Array(arr) = entry {
            let mut tiles = Vec::with_capacity(arr.len());
            for v in arr {
                if let JsonValue::Number(n) = v {
                    // Passable tile ids are byte-sized integers; reject
                    // fractional values rather than silently truncating.
                    if n.fract() == 0.0 && n >= 0.0 && n <= 255.0 {
                        tiles.push(n as u8);
                    }
                }
            }
            out.insert(name, tiles);
        }
    }
    out
}

// ── Tiny JSON parser (only what build.rs needs) ─────────────────────

// ── UI Layout codegen ─────────────────────────────────────────────────────

/// Parse `ui_layouts/components.gui` (if present) into the shared component
/// declarations every screen compile is seeded with.
fn load_component_prelude(v2_dir: &Path) -> Vec<dotzuki_engine_dsl::ast::ComponentDecl> {
    let prelude_path = v2_dir.join("components.gui");
    let Ok(source) = fs::read_to_string(&prelude_path) else {
        return Vec::new();
    };
    let path_str = prelude_path.to_string_lossy().to_string();
    let mut lexer = dotzuki_engine_dsl::lexer::Lexer::new(&source, &path_str);
    let tokens = lexer
        .tokenize()
        .unwrap_or_else(|e| panic!("Lexer errors in {}: {:?}", prelude_path.display(), e));
    let (doc, parse_errors) = dotzuki_engine_dsl::parser::parse(tokens);
    assert!(
        parse_errors.is_empty(),
        "Parser errors in {}: {:?}",
        prelude_path.display(),
        parse_errors
    );
    match doc.unwrap() {
        dotzuki_engine_dsl::ast::Document::Components(decls) => decls,
        other => panic!(
            "Expected only component declarations in {}, got {:?}",
            prelude_path.display(),
            other
        ),
    }
}

/// Compile a .gui DSL file to a schema v2 JSON string via the DSL compiler.
fn compile_gui_to_json(gui_path: &Path, components: &[dotzuki_engine_dsl::ast::ComponentDecl]) -> String {
    let source = fs::read_to_string(gui_path)
        .unwrap_or_else(|e| panic!("read {}: {}", gui_path.display(), e));

    let path_str = gui_path.to_string_lossy().to_string();
    let mut lexer = dotzuki_engine_dsl::lexer::Lexer::new(&source, &path_str);
    let tokens = lexer
        .tokenize()
        .unwrap_or_else(|e| panic!("Lexer errors in {}: {:?}", gui_path.display(), e));

    let (doc, parse_errors) = dotzuki_engine_dsl::parser::parse_with_components(tokens, components);
    assert!(
        parse_errors.is_empty(),
        "Parser errors in {}: {:?}",
        gui_path.display(),
        parse_errors
    );

    let mut screen = match doc.unwrap() {
        dotzuki_engine_dsl::ast::Document::Screen(s) => s,
        other => panic!("Expected Screen document in {}, got {:?}", gui_path.display(), other),
    };

    // The layout registry is keyed by file stem (snake_case), and the v1 JSON
    // layouts set "screen" to that stem. Normalize the compiled .gui screen
    // name to the file stem so the JSON's `screen` field matches the registry
    // key regardless of the identifier used in `screen <Name> { … }`.
    if let Some(stem) = gui_path.file_stem().and_then(|s| s.to_str()) {
        screen.name = stem.to_string();
    }

    dotzuki_engine_dsl::codegen::json_ui::compile_screen(&screen)
        .unwrap_or_else(|e| panic!("Codegen error in {}: {}", gui_path.display(), e))
}

/// Reads `ui_layouts/*.gui` (and `ui_layouts/v1/*.json`) and emits
/// `ui_layouts_gen.rs` into `OUT_DIR`.
///
/// v1 layout files live under `ui_layouts/v1/` and generate compile-time
/// struct definitions (e.g. `MartMainMenuLayout`).  v2 element-based layout
/// files are authored as `.gui` DSL files in the root `ui_layouts/` directory
/// and compiled to JSON at build time.  The compiled JSON is registered so
/// `get_layout_json()` can serve it to tests and the preview tool.
///
/// Generated items:
/// - Per-variant layout structs (e.g. `MartMainMenuLayout`)
/// - `pub static` instances with `Cow::Borrowed(...)` for all fields
/// - `pub fn get_layout_json(screen) -> Option<&'static str>` registry
fn generate_ui_layouts(manifest_dir: &Path, out_dir: &str) {
    let v1_dir = manifest_dir.join("ui_layouts/v1");
    let v2_dir = manifest_dir.join("ui_layouts");

    println!("cargo:rerun-if-changed={}", v1_dir.display());
    println!("cargo:rerun-if-changed={}", v2_dir.display());

    // ── helper: read .json files from a directory ─────────────────────
    let read_json_dir = |dir: &Path| -> Vec<_> {
        match fs::read_dir(dir) {
            Ok(rd) => rd
                .filter_map(|e| e.ok())
                .filter(|e| e.path().extension().and_then(|s| s.to_str()) == Some("json"))
                .collect(),
            Err(_) => Vec::new(),
        }
    };

    let mut v1_entries = read_json_dir(&v1_dir);
    v1_entries.sort_by_key(|e| e.file_name());

    // v1 files must exist (codegen depends on them)
    if v1_entries.is_empty() {
        let out_path = Path::new(out_dir).join("ui_layouts_gen.rs");
        let stub = "// @generated — no ui_layouts/v1/*.json found.\n\
                    pub fn get_layout_json(_screen: &str) -> Option<&'static str> { None }\n";
        fs::write(&out_path, stub)
            .unwrap_or_else(|e| panic!("write {}: {}", out_path.display(), e));
        return;
    }

    let mut out = String::new();
    out.push_str("// @generated by pokered-data/build.rs from ui_layouts/v1/*.json — do not edit.\n\n");
    // No imports needed — included from within ui_layout/schema.rs which
    // already has Cow, BoxDef, CursorDef, LabelDef, DynamicHeight, InkColor,
    // TileRect in scope.

    let mut json_literals: Vec<(String, String)> = Vec::new();

    // ── Process v1 files for struct generation + JSON registry ────────
    for entry in &v1_entries {
        let json_path = entry.path();
        let stem = entry.path().file_stem().unwrap().to_string_lossy().into_owned();
        let content = fs::read_to_string(&json_path)
            .unwrap_or_else(|e| panic!("read {}: {}", json_path.display(), e));
        let parsed: serde_json::Value = serde_json::from_str(&content)
            .unwrap_or_else(|e| panic!("parse {}: {}", json_path.display(), e));

        let version = parsed.get("schema_version").and_then(|v| v.as_u64());
        let screen = parsed["screen"]
            .as_str()
            .unwrap_or_else(|| panic!("{}: missing `screen` field", json_path.display()));

        assert_eq!(
            version,
            Some(1),
            "{}: ui_layouts/v1/ files must have schema_version: 1",
            json_path.display()
        );

        let variants = parsed
            .get("variants")
            .and_then(|v| v.as_object())
            .unwrap_or_else(|| panic!("{}: missing `variants` object", json_path.display()));

        for (variant_name, variant) in variants {
            emit_variant_struct(&mut out, screen, variant_name, variant);
        }

        json_literals.push((stem, content));
    }

    // ── Process v2 .gui files ──────────────────────────────────────
    let mut gui_entries: Vec<_> = fs::read_dir(&v2_dir)
        .unwrap_or_else(|e| panic!("read_dir {}: {}", v2_dir.display(), e))
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().and_then(|s| s.to_str()) == Some("gui"))
        // components.gui is the declarations prelude, not a screen.
        .filter(|e| e.path().file_stem().and_then(|s| s.to_str()) != Some("components"))
        .collect();
    gui_entries.sort_by_key(|e| e.file_name());

    let component_prelude = load_component_prelude(&v2_dir);

    // Every compiled .gui (element-format schema v2), keyed by stem —
    // regardless of v1 precedence. This is the source the v2 layout engine
    // (dotzuki-renderer) consumes for menus migrated off the v1 path.
    let mut gui_v2_literals: Vec<(String, String)> = Vec::new();

    for entry in &gui_entries {
        let stem = entry.path().file_stem().unwrap().to_string_lossy().into_owned();
        let gui_path = entry.path();
        let compiled_json = compile_gui_to_json(&gui_path, &component_prelude);

        // Verify the compiled JSON is valid
        let parsed: serde_json::Value = serde_json::from_str(&compiled_json)
            .unwrap_or_else(|e| panic!("Invalid compiled JSON from {}: {}", gui_path.display(), e));

        let version = parsed.get("schema_version").and_then(|v| v.as_u64());
        assert_eq!(
            version,
            Some(2),
            "{}: compiled .gui must produce schema_version: 2, got {:?}",
            gui_path.display(),
            version
        );

        // The v2 registry always carries the element-format JSON.
        gui_v2_literals.push((stem.clone(), compiled_json.clone()));

        // `get_layout_json` keeps v1 precedence: only register the .gui there
        // for screens that have no v1 (variants) JSON.
        if !json_literals.iter().any(|(s, _)| s == &stem) {
            json_literals.push((stem, compiled_json));
        }
    }

    // ── Emit registry functions ─────────────────────────────────────
    out.push_str("pub fn get_layout_json(screen: &str) -> Option<&'static str> {\n");
    out.push_str("    match screen {\n");
    for (stem, json_str) in &json_literals {
        out.push_str(&format!("        {:?} => Some({:?}),\n", stem, json_str));
    }
    out.push_str("        _ => None,\n    }\n}\n");

    // Element-format (schema v2) JSON for every `.gui` screen, used by menus
    // rendered through the dotzuki-renderer layout engine. Unlike
    // `get_layout_json`, this is NOT shadowed by v1 variants JSON.
    out.push_str("\npub fn get_screen_v2_json(screen: &str) -> Option<&'static str> {\n");
    out.push_str("    match screen {\n");
    for (stem, json_str) in &gui_v2_literals {
        out.push_str(&format!("        {:?} => Some({:?}),\n", stem, json_str));
    }
    out.push_str("        _ => None,\n    }\n}\n");

    let out_path = Path::new(out_dir).join("ui_layouts_gen.rs");
    fs::write(&out_path, out)
        .unwrap_or_else(|e| panic!("write {}: {}", out_path.display(), e));
}

// ── TMX asset embedding ────────────────────────────────────────────────────

/// Scans `assets/maps/` for `.tmx` files and emits `tmx_assets_gen.rs` into
/// `OUT_DIR` containing a static lookup table `ALL_TMX_FILES: &[(&str, &str)]`
/// that maps each file stem to its compile-time embedded content via
/// `include_str!`.
///
/// When no `.tmx` files are found (directory is absent or empty), an empty
/// table is emitted so the consuming code always compiles.
fn generate_tmx_assets(manifest_dir: &Path, out_dir: &str) {
    let assets_dir = manifest_dir.join("../../../../assets");
    let maps_dir = assets_dir.join("maps");

    println!("cargo:rerun-if-changed={}", maps_dir.display());

    let mut entries: Vec<(String, PathBuf)> = Vec::new();
    if maps_dir.is_dir() {
        if let Ok(dir) = fs::read_dir(&maps_dir) {
            for entry in dir.flatten() {
                let path = entry.path();
                if path.extension().and_then(|s| s.to_str()) == Some("tmx") {
                    let stem = path
                        .file_stem()
                        .unwrap()
                        .to_string_lossy()
                        .into_owned();
                    println!("cargo:rerun-if-changed={}", path.display());
                    entries.push((stem, path));
                }
            }
        }
    }
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let out_path = Path::new(out_dir).join("tmx_assets_gen.rs");
    let mut out = fs::File::create(&out_path)
        .unwrap_or_else(|e| panic!("create {}: {}", out_path.display(), e));

    writeln!(
        out,
        "// @generated by pokered-data/build.rs from assets/maps/*.tmx — do not edit.\n"
    )
    .unwrap();

    if entries.is_empty() {
        writeln!(out, "pub static ALL_TMX_FILES: &[(&str, &str)] = &[];").unwrap();
        writeln!(out, "pub const TMX_COUNT: usize = 0;").unwrap();
        return;
    }

    writeln!(out, "pub static ALL_TMX_FILES: &[(&str, &str)] = &[").unwrap();
    for (stem, path) in &entries {
        let path_str = path.to_str().unwrap().replace('\\', "/");
        writeln!(
            out,
            "    ({:?}, include_str!({:?})),",
            stem, path_str
        )
        .unwrap();
    }
    writeln!(out, "];").unwrap();
    writeln!(out, "pub const TMX_COUNT: usize = {};", entries.len()).unwrap();
}

// ── Script asset embedding ─────────────────────────────────────────────────

/// Scans `assets/scripts/` for `.js` files and emits `script_assets_gen.rs`
/// into `OUT_DIR` containing a static lookup table `SCRIPT_FILES:
/// &[(&str, &str)]` that maps each script key (e.g. `"PalletTown/script"`) to
/// its compile-time embedded content via `include_str!`.
///
/// If `assets/scripts/` does not exist or is empty, falls back to scanning
/// the existing `maps/` directory for `script.js` files (the current
/// convention).  When nothing is found, an empty table is emitted so the
/// consuming code always compiles.
fn generate_script_assets(manifest_dir: &Path, out_dir: &str) {
    let assets_dir = manifest_dir.join("../../../../assets");
    let scripts_dir = assets_dir.join("scripts");
    let maps_dir = manifest_dir.join("maps");

    println!("cargo:rerun-if-changed={}", scripts_dir.display());
    println!("cargo:rerun-if-changed={}", maps_dir.display());

    let mut entries: Vec<(String, PathBuf)> = Vec::new();

    // Try assets/scripts/ first (new convention).
    if scripts_dir.is_dir() {
        if let Ok(dir) = fs::read_dir(&scripts_dir) {
            for entry in dir.flatten() {
                let path = entry.path();
                if path.is_file()
                    && path.extension().and_then(|s| s.to_str()) == Some("js")
                {
                    // Use parent directory + stem as the key,
                    // e.g. "PalletTown/script" for assets/scripts/PalletTown/script.js
                    let parent = path
                        .parent()
                        .and_then(|p| p.file_name())
                        .and_then(|s| s.to_str())
                        .unwrap_or("");
                    let stem = path
                        .file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or("");
                    let key = if parent.is_empty() {
                        stem.to_string()
                    } else {
                        format!("{}/{}", parent, stem)
                    };
                    println!("cargo:rerun-if-changed={}", path.display());
                    entries.push((key, path));
                }
            }
        }
    }

    // Fall back to scanning maps/*/script.js (existing convention).
    if entries.is_empty() && maps_dir.is_dir() {
        if let Ok(dir) = fs::read_dir(&maps_dir) {
            for entry in dir.flatten() {
                let path = entry.path();
                if !path.is_dir() {
                    continue;
                }
                let js_path = path.join("script.js");
                if js_path.is_file() {
                    let map_name = path
                        .file_name()
                        .and_then(|s| s.to_str())
                        .unwrap_or("")
                        .to_string();
                    println!("cargo:rerun-if-changed={}", js_path.display());
                    entries.push((format!("{}/script", map_name), js_path));
                }
            }
        }
    }

    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let out_path = Path::new(out_dir).join("script_assets_gen.rs");
    let mut out = fs::File::create(&out_path)
        .unwrap_or_else(|e| panic!("create {}: {}", out_path.display(), e));

    writeln!(
        out,
        "// @generated by pokered-data/build.rs from scripts/*.js — do not edit.\n"
    )
    .unwrap();

    if entries.is_empty() {
        writeln!(out, "pub static SCRIPT_FILES: &[(&str, &str)] = &[];").unwrap();
        writeln!(out, "pub const SCRIPT_COUNT: usize = 0;").unwrap();
        return;
    }

    writeln!(out, "pub static SCRIPT_FILES: &[(&str, &str)] = &[").unwrap();
    for (key, path) in &entries {
        let path_str = path.to_str().unwrap().replace('\\', "/");
        writeln!(
            out,
            "    ({:?}, include_str!({:?})),",
            key, path_str
        )
        .unwrap();
    }
    writeln!(out, "];").unwrap();
    writeln!(out, "pub const SCRIPT_COUNT: usize = {};", entries.len()).unwrap();
}

// ── Compiled .scene embedding ──────────────────────────────────────────────

/// Compiles every `maps/{MapName}/script.scene` to JavaScript at build time
/// (via the dotzuki-engine-dsl compiler) and emits `scene_scripts_gen.rs` into
/// `OUT_DIR` with three static tables:
///
/// - `SCENE_SCRIPTS: &[(&str, &str)]` — map name → compiled JS module
/// - `SCENE_ASTS: &[(&str, &[u8])]` — map name → serialized scene AST
///   (serde_json of `dotzuki_engine_dsl::ast::GameScene`, consumed by the native
///   AST interpreter — see `pokered-core::overworld::native_script`)
/// - `SCENE_CONFIGS: &[(&str, &str)]` — map name → raw `script_config.json`
///
/// The compiled JS is written to `OUT_DIR/scene_js/{MapName}.js` and pulled
/// in via `include_str!` so the generated Rust stays small; ASTs go to
/// `OUT_DIR/scene_asts/{MapName}.bin` (`include_bytes!`). A scene that
/// fails to compile is a hard build error — the `.scene` files are the
/// source of truth for map scripting and a broken one must not ship.
///
/// Shared modules: `maps/shared/*.scene` files are compiled to ASTs under the
/// key `shared/{name}` (e.g. `shared/pokecenter`) and appended to
/// `SCENE_ASTS`. The Boa path's shared JS modules (`shared/*.js`) are
/// embedded separately by dotzuki-engine-script's own build.
fn generate_scene_scripts(manifest_dir: &Path, out_dir: &str) {
    let maps_dir = manifest_dir.join("maps");
    println!("cargo:rerun-if-changed={}", maps_dir.display());

    let mut dir_entries: Vec<_> = fs::read_dir(&maps_dir)
        .unwrap_or_else(|e| panic!("read_dir {}: {}", maps_dir.display(), e))
        .filter_map(|r| r.ok())
        .filter(|e| e.path().is_dir())
        .collect();
    dir_entries.sort_by_key(|e| e.file_name());

    let js_out_dir = Path::new(out_dir).join("scene_js");
    fs::create_dir_all(&js_out_dir)
        .unwrap_or_else(|e| panic!("create {}: {}", js_out_dir.display(), e));
    let ast_out_dir = Path::new(out_dir).join("scene_asts");
    fs::create_dir_all(&ast_out_dir)
        .unwrap_or_else(|e| panic!("create {}: {}", ast_out_dir.display(), e));

    let mut scripts: Vec<(String, PathBuf)> = Vec::new();
    let mut asts: Vec<(String, PathBuf)> = Vec::new();
    let mut configs: Vec<(String, PathBuf)> = Vec::new();

    for entry in dir_entries {
        let path = entry.path();
        let map_name = entry.file_name().to_string_lossy().into_owned();

        let scene_path = path.join("script.scene");
        if scene_path.is_file() {
            println!("cargo:rerun-if-changed={}", scene_path.display());
            let source = fs::read_to_string(&scene_path)
                .unwrap_or_else(|e| panic!("read {}: {}", scene_path.display(), e));
            let js = dotzuki_engine_dsl::compiler::compile_scene_to_js(
                &source,
                &scene_path.to_string_lossy(),
            )
            .unwrap_or_else(|e| panic!("compile {}: {}", scene_path.display(), e));
            let js_path = js_out_dir.join(format!("{}.js", map_name));
            fs::write(&js_path, js)
                .unwrap_or_else(|e| panic!("write {}: {}", js_path.display(), e));
            scripts.push((map_name.clone(), js_path));

            // Native-interpreter path: serialize the parsed AST alongside the
            // JS so pokered-core can run scenes without Boa.
            let ast = dotzuki_engine_dsl::compiler::compile_scene_to_ast(
                &source,
                &scene_path.to_string_lossy(),
            )
            .unwrap_or_else(|e| panic!("parse {} to AST: {}", scene_path.display(), e));
            let ast_bytes = serde_json::to_vec(&ast)
                .unwrap_or_else(|e| panic!("serialize AST {}: {}", scene_path.display(), e));
            let ast_path = ast_out_dir.join(format!("{}.bin", map_name));
            fs::write(&ast_path, ast_bytes)
                .unwrap_or_else(|e| panic!("write {}: {}", ast_path.display(), e));
            asts.push((map_name.clone(), ast_path));
        }

        let config_path = path.join("script_config.json");
        if config_path.is_file() {
            println!("cargo:rerun-if-changed={}", config_path.display());
            configs.push((map_name, config_path));
        }
    }

    // Shared modules (`maps/shared/*.scene`) → ASTs under `shared/{name}`.
    let shared_dir = maps_dir.join("shared");
    if shared_dir.is_dir() {
        let mut shared_entries: Vec<_> = fs::read_dir(&shared_dir)
            .unwrap_or_else(|e| panic!("read_dir {}: {}", shared_dir.display(), e))
            .filter_map(|r| r.ok())
            .filter(|e| {
                e.path().is_file()
                    && e.path().extension().map(|x| x == "scene").unwrap_or(false)
            })
            .collect();
        shared_entries.sort_by_key(|e| e.file_name());
        for entry in shared_entries {
            let path = entry.path();
            let stem = path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or("")
                .to_string();
            println!("cargo:rerun-if-changed={}", path.display());
            let source = fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("read {}: {}", path.display(), e));
            let ast = dotzuki_engine_dsl::compiler::compile_scene_to_ast(
                &source,
                &path.to_string_lossy(),
            )
            .unwrap_or_else(|e| panic!("parse shared scene {}: {}", path.display(), e));
            let ast_bytes = serde_json::to_vec(&ast)
                .unwrap_or_else(|e| panic!("serialize shared AST {}: {}", path.display(), e));
            let ast_path = ast_out_dir.join(format!("shared_{}.bin", stem));
            fs::write(&ast_path, ast_bytes)
                .unwrap_or_else(|e| panic!("write {}: {}", ast_path.display(), e));
            asts.push((format!("shared/{}", stem), ast_path));
        }
    }

    assert!(
        scripts.len() >= 240,
        "generate_scene_scripts: only {} scenes found (expected ~248). Did a script.scene get deleted?",
        scripts.len()
    );

    let out_path = Path::new(out_dir).join("scene_scripts_gen.rs");
    let mut out = fs::File::create(&out_path)
        .unwrap_or_else(|e| panic!("create {}: {}", out_path.display(), e));

    writeln!(
        out,
        "// @generated by pokered-data/build.rs from maps/*/script.scene — do not edit.\n"
    )
    .unwrap();

    writeln!(out, "pub static SCENE_SCRIPTS: &[(&str, &str)] = &[").unwrap();
    for (map_name, js_path) in &scripts {
        let path_str = js_path.to_str().unwrap().replace('\\', "/");
        writeln!(out, "    ({:?}, include_str!({:?})),", map_name, path_str).unwrap();
    }
    writeln!(out, "];").unwrap();

    writeln!(out, "pub static SCENE_ASTS: &[(&str, &[u8])] = &[").unwrap();
    for (map_name, ast_path) in &asts {
        let path_str = ast_path.to_str().unwrap().replace('\\', "/");
        writeln!(out, "    ({:?}, include_bytes!({:?})),", map_name, path_str).unwrap();
    }
    writeln!(out, "];").unwrap();

    writeln!(out, "pub static SCENE_CONFIGS: &[(&str, &str)] = &[").unwrap();
    for (map_name, config_path) in &configs {
        let path_str = config_path.to_str().unwrap().replace('\\', "/");
        writeln!(out, "    ({:?}, include_str!({:?})),", map_name, path_str).unwrap();
    }
    writeln!(out, "];").unwrap();

    writeln!(out, "pub const SCENE_SCRIPT_COUNT: usize = {};", scripts.len()).unwrap();
    writeln!(out, "pub const SCENE_AST_COUNT: usize = {};", asts.len()).unwrap();
}

fn emit_variant_struct(out: &mut String, screen: &str, variant_name: &str, variant: &serde_json::Value) {
    let struct_name = to_pascal_case(screen) + &to_pascal_case(variant_name) + "Layout";
    let static_name = screen.to_uppercase() + "_" + &variant_name.to_uppercase() + "_LAYOUT";
    let cursor_val = variant.get("cursor");
    let have_cursor = cursor_val
        .and_then(|v| v.as_object())
        .map_or(false, |obj| !obj.contains_key("_TODO"));

    // Skip _TODO-only variants
    if !have_cursor
        && !variant.get("children").and_then(|b| b.as_array()).map_or(false, |a| !a.is_empty())
        && !variant.get("primitives").and_then(|b| b.as_array()).map_or(false, |a| !a.is_empty())
        && !variant.get("cursors").is_some()
        && !variant.get("dynamic_labels").is_some()
        && !variant.get("enum_position_map").is_some()
    {
        return; // Skip placeholder variants
    }
    // ─── Struct definition ───
    out.push_str(&format!("pub struct {} {{\n", struct_name));

    emit_collection_struct_fields(out, "children", variant.get("children").and_then(|v| v.as_array()), "BoxDef");
    emit_collection_struct_fields(out, "primitives", variant.get("primitives").and_then(|v| v.as_array()), "PrimitiveDef");
    if variant.get("list").is_some() {
        out.push_str("    pub list: ListParams,\n");
    }
    if have_cursor {
        out.push_str("    pub cursor: CursorDef,\n");
    }
    if variant.get("cursors").is_some() {
        out.push_str("    pub cursors: Cow<'static, [CursorDef]>,\n");
    }
    if variant.get("dynamic_labels").is_some() {
        out.push_str("    pub dynamic_labels: Cow<'static, [(Cow<'static, str>, DynamicLabelDef)]>,\n");
    }
    if variant.get("enum_position_map").is_some() {
        out.push_str("    pub enum_position_map: Cow<'static, [(Cow<'static, str>, i32)]>,\n");
    }
    if variant.get("flex").is_some() {
        out.push_str("    pub flex: FlexContainer,\n");
    }
    out.push_str("}\n\n");

    // ─── Static definition ───
    out.push_str(&format!(
        "pub static {}: {} = {} {{\n",
        static_name, struct_name, struct_name
    ));
    if let Some(children) = variant.get("children").and_then(|v| v.as_array()) {
        for child in children {
            emit_box_def(out, child);
        }
    }
    if let Some(primitives) = variant.get("primitives").and_then(|v| v.as_array()) {
        for primitive in primitives {
            emit_primitive_def(out, primitive);
        }
    }
    if have_cursor {
        emit_cursor_def(out, cursor_val.unwrap());
    }
    if let Some(cursors) = variant.get("cursors").and_then(|v| v.as_array()) {
        emit_cursors_array(out, "cursors", cursors);
    }
    if let Some(dls) = variant.get("dynamic_labels").and_then(|v| v.as_object()) {
        emit_dynamic_labels(out, dls);
    }
    if let Some(epm) = variant.get("enum_position_map").and_then(|v| v.as_object()) {
        emit_enum_position_map(out, epm);
    }
    out.push_str("};\n\n");
}

fn emit_collection_struct_fields(out: &mut String, _key: &str, array: Option<&Vec<serde_json::Value>>, type_name: &str) {
    if let Some(items) = array {
        if !items.is_empty() {
            for item in items {
                let id = item["id"].as_str().unwrap_or("unnamed");
                out.push_str(&format!("    pub {}: {},\n", id, type_name));
            }
        }
    }
}

fn to_pascal_case(s: &str) -> String {
    s.split(|c: char| c == '_' || c == '-')
        .filter(|w| !w.is_empty())
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(c.flat_map(|ch| ch.to_lowercase())).collect(),
            }
        })
        .collect()
}

fn emit_box_def(out: &mut String, box_def: &serde_json::Value) {
    let id = box_def["id"].as_str().unwrap_or("unnamed_box");
    out.push_str(&format!("    {}: BoxDef {{\n", id));
    out.push_str(&format!("        id: Cow::Borrowed({:?}),\n", id));

    let rect = &box_def["rect"];
    emit_tile_rect(out, rect, "rect");

    let color = emit_ink_color_val(&box_def["color"]);
    out.push_str(&format!("        color: {},\n", color));

    let border = box_def.get("border").and_then(|v| v.as_bool()).unwrap_or(true);
    out.push_str(&format!("        border: {},\n", border));

    let z_index = box_def.get("z_index").and_then(|v| v.as_u64()).unwrap_or(0);
    out.push_str(&format!("        z_index: {},\n", z_index));

    let layout = layout_mode_str(box_def.get("layout"));
    out.push_str(&format!("        layout: {},\n", layout));

    // labels (absolute layout)
    out.push_str("        labels: Cow::Borrowed(&[\n");
    if let Some(labels) = box_def.get("labels").and_then(|l| l.as_array()) {
        for label in labels {
            emit_label_def(out, label);
        }
    }
    out.push_str("        ]),\n");

    // ── flex layout fields ──
    let gap = box_def.get("gap").and_then(|v| v.as_u64()).unwrap_or(1);
    out.push_str(&format!("        gap: {},\n", gap));

    emit_edge_insets(out, box_def.get("padding"), "padding");

    let justify = justify_str(box_def.get("justify"));
    out.push_str(&format!("        justify: {},\n", justify));

    let align = align_str(box_def.get("align"));
    out.push_str(&format!("        align: {},\n", align));

    out.push_str("        items: Cow::Borrowed(&[\n");
    if let Some(items) = box_def.get("items").and_then(|v| v.as_array()) {
        for item in items {
            let text = item["text"].as_str().unwrap_or("");
            let item_color = emit_ink_color_val(&item["color"]);
            out.push_str(&format!(
                "            FlexItem {{ text: Cow::Borrowed({:?}), color: {} }},\n",
                text, item_color
            ));
        }
    }
    out.push_str("        ]),\n");

    if let Some(cursor) = box_def.get("cursor") {
        out.push_str("        cursor: Some(CursorDef {\n");
        emit_cursor_def_fields(out, cursor);
        out.push_str("        }),\n");
    } else {
        out.push_str("        cursor: None,\n");
    }

    let name_w = box_def.get("item_name_width").and_then(|v| v.as_u64()).unwrap_or(14);
    let qty_w = box_def.get("qty_width").and_then(|v| v.as_u64()).unwrap_or(2);
    out.push_str(&format!("        item_name_width: {},\n", name_w));
    out.push_str(&format!("        qty_width: {},\n", qty_w));

    let width_mode = size_mode_str(box_def.get("width"));
    let height_mode = size_mode_str(box_def.get("height"));
    out.push_str(&format!("        width_mode: {},\n", width_mode));
    out.push_str(&format!("        height_mode: {},\n", height_mode));

    out.push_str(&format!("        min_width: {},\n", opt_u32_field(box_def, "min_width")));
    out.push_str(&format!("        max_width: {},\n", opt_u32_field(box_def, "max_width")));
    out.push_str(&format!("        min_height: {},\n", opt_u32_field(box_def, "min_height")));
    out.push_str(&format!("        max_height: {},\n", opt_u32_field(box_def, "max_height")));

    // ── list layout fields ──
    out.push_str(&format!("        item_start_ty: {},\n", opt_u32_field(box_def, "item_start_ty")));
    out.push_str(&format!("        row_step: {},\n", opt_u32_field(box_def, "row_step")));
    out.push_str(&format!("        max_visible_rows: {},\n", opt_u32_field(box_def, "max_visible_rows")));

    // dynamic_height
    match box_def.get("dynamic_height").filter(|dh| !dh.is_null()) {
        Some(dh) => {
            let extra = dh["extra_per_row"].as_u64().expect("dynamic_height.extra_per_row must be u32");
            out.push_str(&format!(
                "        dynamic_height: Some(DynamicHeight {{ extra_per_row: {} }}),\n",
                extra
            ));
        }
        _ => out.push_str("        dynamic_height: None,\n"),
    }

    // ── text layout fields ──
    out.push_str(&format!("        text_start_tx: {},\n", opt_u32_field(box_def, "text_start_tx")));
    out.push_str(&format!("        text_start_ty: {},\n", opt_u32_field(box_def, "text_start_ty")));
    out.push_str(&format!("        line_height: {},\n", opt_u32_field(box_def, "line_height")));
    out.push_str(&format!("        max_lines: {},\n", opt_u32_field(box_def, "max_lines")));
    out.push_str(&format!("        line_width: {},\n", opt_u32_field(box_def, "line_width")));
    out.push_str(&format!("        line_width_zh: {},\n", opt_u32_field(box_def, "line_width_zh")));

    out.push_str("    },\n");
}

fn emit_edge_insets(out: &mut String, padding: Option<&serde_json::Value>, field: &str) {
    let top = padding.and_then(|p| p.get("top")).and_then(|v| v.as_u64()).unwrap_or(1);
    let bot = padding.and_then(|p| p.get("bottom")).and_then(|v| v.as_u64()).unwrap_or(1);
    let left = padding.and_then(|p| p.get("left")).and_then(|v| v.as_u64()).unwrap_or(1);
    let right = padding.and_then(|p| p.get("right")).and_then(|v| v.as_u64()).unwrap_or(1);
    out.push_str(&format!(
        "        {}: EdgeInsets {{ top: {}, bottom: {}, left: {}, right: {} }},\n",
        field, top, bot, left, right
    ));
}

fn emit_flex_container(out: &mut String, flex: &serde_json::Value) {
    let id = flex["id"].as_str().unwrap_or("flex");
    out.push_str(&format!("    flex: FlexContainer {{\n"));
    out.push_str(&format!("        id: Cow::Borrowed({:?}),\n", id));

    emit_tile_rect(out, &flex["rect"], "rect");

    let color = emit_ink_color_val(&flex["color"]);
    out.push_str(&format!("        color: {},\n", color));

    // Size modes
    let width_mode = size_mode_str(flex.get("width"));
    let height_mode = size_mode_str(flex.get("height"));
    out.push_str(&format!("        width_mode: {},\n", width_mode));
    out.push_str(&format!("        height_mode: {},\n", height_mode));

    // Min/max
    out.push_str(&format!("        min_width: {},\n", opt_u32_field(flex, "min_width")));
    out.push_str(&format!("        max_width: {},\n", opt_u32_field(flex, "max_width")));
    out.push_str(&format!("        min_height: {},\n", opt_u32_field(flex, "min_height")));
    out.push_str(&format!("        max_height: {},\n", opt_u32_field(flex, "max_height")));

    // Padding
    let pad = flex.get("padding");
    let pad_top = pad.and_then(|p| p.get("top")).and_then(|v| v.as_u64()).unwrap_or(1);
    let pad_bot = pad.and_then(|p| p.get("bottom")).and_then(|v| v.as_u64()).unwrap_or(1);
    let pad_left = pad.and_then(|p| p.get("left")).and_then(|v| v.as_u64()).unwrap_or(1);
    let pad_right = pad.and_then(|p| p.get("right")).and_then(|v| v.as_u64()).unwrap_or(1);
    out.push_str(&format!(
        "        padding: EdgeInsets {{ top: {}, bottom: {}, left: {}, right: {} }},\n",
        pad_top, pad_bot, pad_left, pad_right
    ));

    let gap = flex.get("gap").and_then(|v| v.as_u64()).unwrap_or(1);
    out.push_str(&format!("        gap: {},\n", gap));

    // Justify / align
    let justify = justify_str(flex.get("justify"));
    let align = align_str(flex.get("align"));
    out.push_str(&format!("        justify: {},\n", justify));
    out.push_str(&format!("        align: {},\n", align));

    // Items
    out.push_str("        items: Cow::Borrowed(&[\n");
    if let Some(items) = flex.get("items").and_then(|v| v.as_array()) {
        for item in items {
            let text = item["text"].as_str().unwrap_or("");
            let item_color = emit_ink_color_val(&item["color"]);
            out.push_str(&format!(
                "            FlexItem {{ text: Cow::Borrowed({:?}), color: {} }},\n",
                text, item_color
            ));
        }
    }
    out.push_str("        ]),\n");

    let name_w = flex.get("item_name_width").and_then(|v| v.as_u64()).unwrap_or(14);
    let qty_w = flex.get("qty_width").and_then(|v| v.as_u64()).unwrap_or(2);
    out.push_str(&format!("        item_name_width: {},\n", name_w));
    out.push_str(&format!("        qty_width: {},\n", qty_w));

    // Cursor
    if let Some(cursor) = flex.get("cursor") {
        out.push_str("        cursor: Some(CursorDef {\n");
        emit_cursor_def_fields(out, cursor);
        out.push_str("        }),\n");
    } else {
        out.push_str("        cursor: None,\n");
    }

    out.push_str("    },\n");
}

fn layout_mode_str(val: Option<&serde_json::Value>) -> &'static str {
    match val.and_then(|v| v.as_str()) {
        Some("flex") => "LayoutMode::Flex",
        Some("list") => "LayoutMode::List",
        _ => "LayoutMode::Absolute",
    }
}

fn size_mode_str(val: Option<&serde_json::Value>) -> &'static str {
    match val.and_then(|v| v.as_str()) {
        Some("auto") => "SizeMode::Auto",
        _ => "SizeMode::Fixed",
    }
}

fn justify_str(val: Option<&serde_json::Value>) -> &'static str {
    match val.and_then(|v| v.as_str()) {
        Some("center") => "Justify::Center",
        Some("end") => "Justify::End",
        _ => "Justify::Start",
    }
}

fn align_str(val: Option<&serde_json::Value>) -> &'static str {
    match val.and_then(|v| v.as_str()) {
        Some("center") => "Align::Center",
        Some("end") => "Align::End",
        _ => "Align::Start",
    }
}

fn emit_label_def(out: &mut String, label: &serde_json::Value) {
    let tx = label["tx"].as_u64().unwrap_or(0);
    let ty = label["ty"].as_u64().unwrap_or(0);
    let text = label["text"].as_str().unwrap_or("");
    let color = emit_ink_color_val(&label["color"]);
    let tile_ids = label.get("tile_ids").and_then(|v| v.as_array());
    let tile_ids_expr = match tile_ids {
        Some(arr) if !arr.is_empty() => {
            let bytes: Vec<String> = arr
                .iter()
                .map(|v| format!("{}u8", v.as_u64().expect("tile_ids entries must be u8")))
                .collect();
            format!("Cow::Borrowed(&[{}])", bytes.join(", "))
        }
        _ => "Cow::Borrowed(&[])".to_string(),
    };
    out.push_str(&format!(
        "            LabelDef {{ tx: {}, ty: {}, text: Cow::Borrowed({:?}), color: {}, tile_ids: {} }},\n",
        tx, ty, text, color, tile_ids_expr
    ));
}

fn emit_cursor_def(out: &mut String, cursor: &serde_json::Value) {
    out.push_str("    cursor: CursorDef {\n");
    emit_cursor_def_fields(out, cursor);
    out.push_str("    },\n");
}

fn emit_cursor_def_fields(out: &mut String, cursor: &serde_json::Value) {
    let tx = cursor["tx"].as_u64().unwrap_or(1);
    let base_ty = cursor["base_ty"].as_u64().unwrap_or(1);
    let row_step = cursor["row_step"].as_u64().unwrap_or(2);
    let glyph = cursor["glyph"].as_str().unwrap_or("\u{25B6}");
    let color = emit_ink_color_val(&cursor["color"]);
    let col_step = opt_u32_field(cursor, "col_step");
    let base_tx = opt_u32_field(cursor, "base_tx");
    out.push_str(&format!(
        "        tx: {}, base_ty: {}, row_step: {}, glyph: '{}', color: {}, col_step: {}, base_tx: {},\n",
        tx, base_ty, row_step, glyph.chars().next().unwrap_or('\u{25B6}'), color, col_step, base_tx
    ));
}

fn opt_u32_field(v: &serde_json::Value, key: &str) -> String {
    match v.get(key).and_then(|val| val.as_u64()) {
        Some(n) => format!("Some({})", n),
        None => "None".to_string(),
    }
}

fn emit_primitive_def(out: &mut String, prim: &serde_json::Value) {
    let id = prim["id"].as_str().unwrap_or("unnamed_prim");
    out.push_str(&format!("    {}: PrimitiveDef {{\n", id));
    out.push_str(&format!("        id: Cow::Borrowed({:?}),\n", id));

    let parent_id = match prim.get("parent_id").and_then(|v| v.as_str()) {
        Some(pid) => format!("Some(Cow::Borrowed({:?}))", pid),
        _ => "None".to_string(),
    };
    out.push_str(&format!("        parent_id: {},\n", parent_id));

    let color = emit_ink_color_val(&prim["color"]);
    out.push_str(&format!("        color: {},\n", color));

    emit_primitive_kind(out, prim);
    out.push_str("    },\n");
}

fn emit_primitive_kind(out: &mut String, prim: &serde_json::Value) {
    let kind = prim["kind"].as_str().unwrap_or_else(|| {
        panic!(
            "primitive {}: missing 'kind' field",
            prim["id"].as_str().unwrap_or("?")
        )
    });
    match kind {
        "hp_bar" => {
            let tx = prim["tx"].as_u64().unwrap_or(0);
            let ty = prim["ty"].as_u64().unwrap_or(0);
            let wt = prim["width_tiles"].as_u64().unwrap_or(0);
            out.push_str(&format!(
                "        kind: PrimitiveKind::HpBar {{ tx: {}, ty: {}, width_tiles: {} }},\n",
                tx, ty, wt
            ));
        }
        "bracket_box" => {
            let rx = prim["rect"]["tx"].as_u64().unwrap_or(0);
            let ry = prim["rect"]["ty"].as_u64().unwrap_or(0);
            let rw = prim["rect"]["tw"].as_u64().unwrap_or(0);
            let rh = prim["rect"]["th"].as_u64().unwrap_or(0);
            let sides = emit_bracket_sides(prim.get("sides"));
            let with_arrow = prim.get("with_arrow").and_then(|v| v.as_bool()).unwrap_or(false);
            out.push_str(&format!(
                "        kind: PrimitiveKind::BracketBox {{ rect: TileRect::new({}, {}, {}, {}), sides: {}, with_arrow: {} }},\n",
                rx, ry, rw, rh, sides, with_arrow
            ));
        }
        "vline" => {
            let tx = prim["tx"].as_u64().unwrap_or(0);
            let ty = prim["ty"].as_u64().unwrap_or(0);
            let len = prim["length_tiles"].as_u64().unwrap_or(0);
            out.push_str(&format!(
                "        kind: PrimitiveKind::Vline {{ tx: {}, ty: {}, length_tiles: {} }},\n",
                tx, ty, len
            ));
        }
        "hline" => {
            let tx = prim["tx"].as_u64().unwrap_or(0);
            let ty = prim["ty"].as_u64().unwrap_or(0);
            let len = prim["length_tiles"].as_u64().unwrap_or(0);
            out.push_str(&format!(
                "        kind: PrimitiveKind::Hline {{ tx: {}, ty: {}, length_tiles: {} }},\n",
                tx, ty, len
            ));
        }
        "pixel_rect" => {
            let px = prim["px"].as_u64().unwrap_or(0);
            let py = prim["py"].as_u64().unwrap_or(0);
            let pw = prim["pw"].as_u64().unwrap_or(0);
            let ph = prim["ph"].as_u64().unwrap_or(0);
            out.push_str(&format!(
                "        kind: PrimitiveKind::PixelRect {{ px: {}, py: {}, pw: {}, ph: {} }},\n",
                px, py, pw, ph
            ));
        }
        other => panic!(
            "primitive {}: unknown kind {:?}",
            prim["id"].as_str().unwrap_or("?"),
            other
        ),
    }
}

fn emit_bracket_sides(sides: Option<&serde_json::Value>) -> String {
    match sides {
        Some(obj) => {
            let top = obj.get("top").and_then(|v| v.as_bool()).unwrap_or(false);
            let bottom = obj.get("bottom").and_then(|v| v.as_bool()).unwrap_or(false);
            let left = obj.get("left").and_then(|v| v.as_bool()).unwrap_or(false);
            let right = obj.get("right").and_then(|v| v.as_bool()).unwrap_or(false);
            format!(
                "BracketSides {{ top: {}, bottom: {}, left: {}, right: {} }}",
                top, bottom, left, right
            )
        }
        None => "BracketSides { top: false, bottom: false, left: false, right: false }".to_string(),
    }
}

fn emit_list_params(out: &mut String, list: &serde_json::Value) {
    out.push_str("    list: ListParams {\n");
    let its = opt_u32_field(list, "item_start_ty");
    let rs = opt_u32_field(list, "row_step");
    let mvr = opt_u32_field(list, "max_visible_rows");
    out.push_str(&format!("        item_start_ty: {},\n", its));
    out.push_str(&format!("        row_step: {},\n", rs));
    out.push_str(&format!("        max_visible_rows: {},\n", mvr));
    if let Some(cursor) = list.get("cursor").filter(|v| !v.is_null()) {
        out.push_str("        cursor: Some(CursorDef {\n");
        let tx = cursor["tx"].as_u64().unwrap_or(0);
        let base_ty = cursor["base_ty"].as_u64().unwrap_or(0);
        let row_step = cursor["row_step"].as_u64().unwrap_or(2);
        let glyph = cursor["glyph"].as_str().unwrap_or("\u{25B6}");
        let color = emit_ink_color_val(&cursor["color"]);
        let col_step = opt_u32_field(cursor, "col_step");
        let base_tx = opt_u32_field(cursor, "base_tx");
        out.push_str(&format!(
            "            tx: {}, base_ty: {}, row_step: {}, glyph: '{}', color: {}, col_step: {}, base_tx: {},\n",
            tx, base_ty, row_step, glyph.chars().next().unwrap_or('\u{25B6}'), color, col_step, base_tx
        ));
        out.push_str("        }),\n");
    } else {
        out.push_str("        cursor: None,\n");
    }
    out.push_str("    },\n");
}

fn emit_cursors_array(out: &mut String, field_name: &str, cursors: &[serde_json::Value]) {
    out.push_str(&format!(
        "    {}: Cow::Borrowed(&[\n",
        field_name
    ));
    for cursor in cursors {
        let tx = cursor["tx"].as_u64().unwrap_or(1);
        let base_ty = cursor["base_ty"].as_u64().unwrap_or(1);
        let row_step = cursor["row_step"].as_u64().unwrap_or(2);
        let glyph = cursor["glyph"].as_str().unwrap_or("\u{25B6}");
        let color = emit_ink_color_val(&cursor["color"]);
        let col_step = opt_u32_field(cursor, "col_step");
        let base_tx = opt_u32_field(cursor, "base_tx");
        out.push_str(&format!(
            "        CursorDef {{ tx: {}, base_ty: {}, row_step: {}, glyph: '{}', color: {}, col_step: {}, base_tx: {} }},\n",
            tx, base_ty, row_step, glyph.chars().next().unwrap_or('\u{25B6}'), color, col_step, base_tx
        ));
    }
    out.push_str("    ]),\n");
}

fn emit_dynamic_labels(out: &mut String, dls: &serde_json::Map<String, serde_json::Value>) {
    out.push_str("    dynamic_labels: Cow::Borrowed(&[\n");
    for (key, dl) in dls {
        let parent = dl["parent"].as_str().unwrap_or("screen");
        let tx = dl["tx"].as_u64().unwrap_or(0);
        let ty = dl["ty"].as_u64().unwrap_or(0);
        let color = emit_ink_color_val(&dl["color"]);
        let text = match dl.get("text").and_then(|v| v.as_str()) {
            Some(t) => format!("Some(Cow::Borrowed({:?}))", t),
            None => "None".to_string(),
        };
        out.push_str(&format!(
            "        (Cow::Borrowed({:?}), DynamicLabelDef {{ parent: Cow::Borrowed({:?}), tx: {}, ty: {}, text: {}, color: {} }}),\n",
            key, parent, tx, ty, text, color
        ));
    }
    out.push_str("    ]),\n");
}

fn emit_enum_position_map(out: &mut String, epm: &serde_json::Map<String, serde_json::Value>) {
    out.push_str("    enum_position_map: Cow::Borrowed(&[\n");
    for (key, val) in epm {
        let num = val.as_i64().unwrap_or(0) as i32;
        out.push_str(&format!(
            "        (Cow::Borrowed({:?}), {}),\n",
            key, num
        ));
    }
    out.push_str("    ]),\n");
}

fn emit_tile_rect(out: &mut String, rect: &serde_json::Value, field_name: &str) {
    let tx = rect["tx"].as_u64().unwrap_or(0);
    let ty = rect["ty"].as_u64().unwrap_or(0);
    let tw = rect["tw"].as_u64().unwrap_or(0);
    let th = rect["th"].as_u64().unwrap_or(0);
    out.push_str(&format!(
        "        {}: TileRect::new({}, {}, {}, {}),\n",
        field_name, tx, ty, tw, th
    ));
}

fn emit_ink_color_val(val: &serde_json::Value) -> String {
    match val.as_str().unwrap_or("Black") {
        "Black" => "InkColor::Black".into(),
        "DarkGray" => "InkColor::DarkGray".into(),
        "LightGray" => "InkColor::LightGray".into(),
        "White" => "InkColor::White".into(),
        "HpFull" => "InkColor::HpFull".into(),
        "HpCaution" => "InkColor::HpCaution".into(),
        "HpCritical" => "InkColor::HpCritical".into(),
        other => panic!("unknown InkColor value: {:?}", other),
    }
}

// ── JSON parser (simple, zero-dep) ────────────────────────────────────────

#[derive(Debug)]
#[allow(dead_code)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    #[allow(dead_code)]
    fn get(&self, key: &str) -> Option<&JsonValue> {
        match self {
            JsonValue::Object(entries) => {
                entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
            }
            _ => None,
        }
    }
}

fn parse_json(s: &str) -> Option<JsonValue> {
    let mut chars: Vec<char> = s.chars().collect();
    let mut idx = 0;
    let v = parse_value(&mut chars, &mut idx)?;
    skip_ws(&chars, &mut idx);
    // Trailing content after the top-level value is intentionally ignored
    // (e.g. trailing newlines that text editors add) — this parser is only
    // used for the well-known schema written by the editor's vite middleware.
    Some(v)
}

fn parse_value(chars: &mut Vec<char>, idx: &mut usize) -> Option<JsonValue> {
    skip_ws(chars, idx);
    if *idx >= chars.len() {
        return None;
    }
    let c = chars[*idx];
    match c {
        '{' => parse_object(chars, idx),
        '[' => parse_array(chars, idx),
        '"' => parse_string(chars, idx).map(JsonValue::String),
        't' | 'f' => parse_bool(chars, idx).map(JsonValue::Bool),
        'n' => parse_null(chars, idx),
        '-' | '0'..='9' => parse_number(chars, idx).map(JsonValue::Number),
        _ => None,
    }
}

fn skip_ws(chars: &[char], idx: &mut usize) {
    while *idx < chars.len() && chars[*idx].is_whitespace() {
        *idx += 1;
    }
}

fn expect(chars: &[char], idx: &mut usize, c: char) -> Option<()> {
    skip_ws(chars, idx);
    if *idx < chars.len() && chars[*idx] == c {
        *idx += 1;
        Some(())
    } else {
        None
    }
}

fn parse_object(chars: &mut Vec<char>, idx: &mut usize) -> Option<JsonValue> {
    expect(chars, idx, '{')?;
    let mut entries: Vec<(String, JsonValue)> = Vec::new();
    skip_ws(chars, idx);
    if *idx < chars.len() && chars[*idx] == '}' {
        *idx += 1;
        return Some(JsonValue::Object(entries));
    }
    loop {
        skip_ws(chars, idx);
        let key = parse_string(chars, idx)?;
        expect(chars, idx, ':')?;
        let val = parse_value(chars, idx)?;
        entries.push((key, val));
        skip_ws(chars, idx);
        if *idx < chars.len() && chars[*idx] == ',' {
            *idx += 1;
            continue;
        }
        break;
    }
    expect(chars, idx, '}')?;
    Some(JsonValue::Object(entries))
}

fn parse_array(chars: &mut Vec<char>, idx: &mut usize) -> Option<JsonValue> {
    expect(chars, idx, '[')?;
    let mut items: Vec<JsonValue> = Vec::new();
    skip_ws(chars, idx);
    if *idx < chars.len() && chars[*idx] == ']' {
        *idx += 1;
        return Some(JsonValue::Array(items));
    }
    loop {
        items.push(parse_value(chars, idx)?);
        skip_ws(chars, idx);
        if *idx < chars.len() && chars[*idx] == ',' {
            *idx += 1;
            continue;
        }
        break;
    }
    expect(chars, idx, ']')?;
    Some(JsonValue::Array(items))
}

fn parse_string(chars: &mut Vec<char>, idx: &mut usize) -> Option<String> {
    skip_ws(chars, idx);
    if *idx >= chars.len() || chars[*idx] != '"' {
        return None;
    }
    *idx += 1;
    let mut s = String::new();
    while *idx < chars.len() {
        let c = chars[*idx];
        *idx += 1;
        if c == '"' {
            return Some(s);
        }
        if c == '\\' && *idx < chars.len() {
            let esc = chars[*idx];
            *idx += 1;
            match esc {
                '"' => s.push('"'),
                '\\' => s.push('\\'),
                '/' => s.push('/'),
                'n' => s.push('\n'),
                't' => s.push('\t'),
                'r' => s.push('\r'),
                'b' => s.push('\u{08}'),
                'f' => s.push('\u{0C}'),
                'u' => {
                    if *idx + 4 > chars.len() {
                        return None;
                    }
                    let hex: String = chars[*idx..*idx + 4].iter().collect();
                    *idx += 4;
                    let code = u32::from_str_radix(&hex, 16).ok()?;
                    if let Some(ch) = char::from_u32(code) {
                        s.push(ch);
                    }
                }
                other => s.push(other),
            }
        } else {
            s.push(c);
        }
    }
    None
}

fn parse_bool(chars: &mut Vec<char>, idx: &mut usize) -> Option<bool> {
    if chars[*idx..].starts_with(&['t', 'r', 'u', 'e']) {
        *idx += 4;
        Some(true)
    } else if chars[*idx..].starts_with(&['f', 'a', 'l', 's', 'e']) {
        *idx += 5;
        Some(false)
    } else {
        None
    }
}

fn parse_null(chars: &mut Vec<char>, idx: &mut usize) -> Option<JsonValue> {
    if chars[*idx..].starts_with(&['n', 'u', 'l', 'l']) {
        *idx += 4;
        Some(JsonValue::Null)
    } else {
        None
    }
}

fn parse_number(chars: &mut Vec<char>, idx: &mut usize) -> Option<f64> {
    let start = *idx;
    if chars[*idx] == '-' {
        *idx += 1;
    }
    while *idx < chars.len() {
        let c = chars[*idx];
        if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
            *idx += 1;
        } else {
            break;
        }
    }
    let s: String = chars[start..*idx].iter().collect();
    s.parse::<f64>().ok()
}

// ── Item + Shop codegen ────────────────────────────────────────────────────

/// Reads `data/items/*.json` and `data/shops/*.json` (the editor's
/// source-of-truth) and emits `OUT_DIR/item_data_gen.rs` containing:
///   - `ITEM_DATA: [ItemData; 83]` — the canonical item definitions
///   - `item_data_for(id: &str) -> Option<&'static ItemData>` — string-lookup
///   - `SHOP_INVENTORIES: &[(&str, &[&str])]` — shop → item list map
///   - `shop_inventory_for(shop_id: ShopId) -> &'static [ItemId]`
///   - `shop_name_for(shop_id: ShopId) -> &'static str`
///
/// Iteration order for ITEM_DATA follows `item_list.json` (same as the
/// original `ItemId` numeric order, 0x01..0x53).
fn generate_item_data(manifest_dir: &Path, out_dir: &str) {
    let items_dir = manifest_dir.join("data/items");
    let shops_dir = manifest_dir.join("data/shops");

    println!("cargo:rerun-if-changed={}", items_dir.display());
    println!("cargo:rerun-if-changed={}", shops_dir.display());

    // ── Read item_list.json for ordering ─────────────────────────────────
    let list_path = items_dir.join("item_list.json");
    let list_text = fs::read_to_string(&list_path)
        .unwrap_or_else(|e| panic!("read {}: {}", list_path.display(), e));
    let list_json: serde_json::Value = serde_json::from_str(&list_text)
        .unwrap_or_else(|e| panic!("parse {}: {}", list_path.display(), e));
    let items = list_json["items"]
        .as_array()
        .unwrap_or_else(|| panic!("{}: missing 'items' array", list_path.display()));
    assert!(
        items.len() >= 83,
        "{}: expected at least 83 items, got {}",
        list_path.display(),
        items.len()
    );

    // ── Read all item JSON files ─────────────────────────────────────────
    // We'll store parsed data so we can emit both the array and the lookup fn
    // with the same data.
    struct ParsedItem {
        id: String,
        name: String,
        price: u16,
        is_key_item: bool,
    }
    let mut parsed_items: Vec<ParsedItem> = Vec::with_capacity(items.len());

    for item_name in items {
        let item_name_str = item_name
            .as_str()
            .unwrap_or_else(|| panic!("{}: item name not a string", list_path.display()));
        let path = items_dir.join(format!("{}.json", item_name_str));
        println!("cargo:rerun-if-changed={}", path.display());

        let text = fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("read {}: {}", path.display(), e));
        let v: serde_json::Value = serde_json::from_str(&text)
            .unwrap_or_else(|e| panic!("parse {}: {}", path.display(), e));

        let id = v["id"]
            .as_str()
            .unwrap_or_else(|| panic!("{}: missing 'id'", path.display()));
        assert_eq!(
            id, item_name_str,
            "{}: 'id' field {:?} doesn't match filename",
            path.display(),
            id
        );

        let name = v["name"]
            .as_str()
            .unwrap_or_else(|| panic!("{}: missing 'name'", path.display()));
        let price = v["price"].as_u64().unwrap_or(0) as u16;
        let is_key_item = v["key_item"].as_bool().unwrap_or(false);

        parsed_items.push(ParsedItem {
            id: id.to_string(),
            name: name.to_string(),
            price,
            is_key_item,
        });
    }

    // ── Read all shop JSON files ─────────────────────────────────────────
    struct ShopEntry {
        shop_id: String,
        display_name: String,
        item_ids: Vec<String>,
    }

    let mut shop_entries: Vec<ShopEntry> = Vec::new();
    if shops_dir.is_dir() {
        let mut dir_entries: Vec<_> = fs::read_dir(&shops_dir)
            .unwrap_or_else(|e| panic!("read_dir {}: {}", shops_dir.display(), e))
            .filter_map(|r| r.ok())
            .filter(|e| {
                e.path().extension().and_then(|s| s.to_str()) == Some("json")
            })
            .collect();
        dir_entries.sort_by_key(|e| e.file_name());

        for entry in &dir_entries {
            let path = entry.path();
            let stem = path
                .file_stem()
                .unwrap()
                .to_string_lossy()
                .into_owned();
            println!("cargo:rerun-if-changed={}", path.display());

            let text = fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("read {}: {}", path.display(), e));
            let v: serde_json::Value = serde_json::from_str(&text)
                .unwrap_or_else(|e| panic!("parse {}: {}", path.display(), e));

            let shop_id = v["id"]
                .as_str()
                .unwrap_or_else(|| panic!("{}: missing 'id'", path.display()));
            assert_eq!(
                shop_id, stem,
                "{}: 'id' field {:?} doesn't match filename",
                path.display(),
                shop_id
            );

            let display_name = v["name"]
                .as_str()
                .unwrap_or_else(|| panic!("{}: missing 'name'", path.display()));
            let items_list = v["items"]
                .as_array()
                .unwrap_or_else(|| panic!("{}: missing 'items' array", path.display()));

            let item_ids: Vec<String> = items_list
                .iter()
                .map(|i| {
                    i.as_str()
                        .unwrap_or_else(|| panic!("{}: item not a string", path.display()))
                        .to_string()
                })
                .collect();

            shop_entries.push(ShopEntry {
                shop_id: stem,
                display_name: display_name.to_string(),
                item_ids,
            });
        }
    }

    // ── Emit item_data_gen.rs ────────────────────────────────────────────
    let out_path = Path::new(out_dir).join("item_data_gen.rs");
    let mut out = fs::File::create(&out_path)
        .unwrap_or_else(|e| panic!("create {}: {}", out_path.display(), e));

    writeln!(
        out,
        "// @generated by pokered-data/build.rs from data/items/*.json and data/shops/*.json — do not edit.\n"
    )
    .unwrap();

    // ── ITEM_DATA array ──────────────────────────────────────────────────
    writeln!(out, "pub const ITEM_DATA: &[ItemData] = &[").unwrap();
    for item in &parsed_items {
        writeln!(out, "    ItemData {{").unwrap();
        writeln!(out, "        id: ItemId::{},", item.id).unwrap();
        writeln!(out, "        name: {:?},", item.name).unwrap();
        writeln!(out, "        price: {},", item.price).unwrap();
        writeln!(out, "        is_key_item: {},", item.is_key_item).unwrap();
        writeln!(out, "    }},").unwrap();
    }
    writeln!(out, "];\n").unwrap();

    // ── item_data_for lookup ─────────────────────────────────────────────
    writeln!(
        out,
        "pub fn item_data_for(id: &str) -> Option<&'static ItemData> {{"
    )
    .unwrap();
    writeln!(out, "    match id {{").unwrap();
    for (i, item) in parsed_items.iter().enumerate() {
        writeln!(
            out,
            "        {:?} => Some(&ITEM_DATA[{}]),",
            item.id, i
        )
        .unwrap();
    }
    writeln!(out, "        _ => None,").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}\n").unwrap();

    // ── SHOP_INVENTORIES const ───────────────────────────────────────────
    writeln!(
        out,
        "pub const SHOP_INVENTORIES: &[(&str, &[&str])] = &["
    )
    .unwrap();
    for shop in &shop_entries {
        write!(out, "    ({:?}, &[", shop.shop_id).unwrap();
        for (j, iid) in shop.item_ids.iter().enumerate() {
            if j > 0 {
                write!(out, ", ").unwrap();
            }
            write!(out, "{:?}", iid).unwrap();
        }
        writeln!(out, "]),").unwrap();
    }
    writeln!(out, "];\n").unwrap();

    // ── shop_inventory_for function ──────────────────────────────────────
    writeln!(
        out,
        "pub fn shop_inventory_for(shop_id: ShopId) -> &'static [ItemId] {{"
    )
    .unwrap();
    writeln!(out, "    match shop_id {{").unwrap();
    for shop in &shop_entries {
        write!(out, "        ShopId::{} => &[", shop.shop_id).unwrap();
        for (j, iid) in shop.item_ids.iter().enumerate() {
            if j > 0 {
                write!(out, ", ").unwrap();
            }
            write!(out, "ItemId::{}", iid).unwrap();
        }
        writeln!(out, "],").unwrap();
    }
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}\n").unwrap();

    // ── shop_name_for function ─────────────────────────────────────────
    writeln!(
        out,
        "pub fn shop_name_for(shop_id: ShopId) -> &'static str {{"
    )
    .unwrap();
    writeln!(out, "    match shop_id {{").unwrap();
    for shop in &shop_entries {
        writeln!(
            out,
            "        ShopId::{} => {:?},",
            shop.shop_id, shop.display_name
        )
        .unwrap();
    }
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
}
